int font_cn_index(unsigned int codepoint)
{
    int lo = 0, hi = FONT_CN_COUNT - 1;

    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (s_cp[mid] == codepoint) return mid;
        if (s_cp[mid] < codepoint)  lo = mid + 1;
        else                         hi = mid - 1;
    }
    return -1;
}

const unsigned char *font_cn_glyph(int index)
{
    if (index < 0 || index >= FONT_CN_COUNT) return 0;
    return s_glyph[index];
}
